#include <atomic>

class SpinLock {
public:
    SpinLock() = default;
    SpinLock(const SpinLock&) = delete;             // a copied lock
    SpinLock& operator=(const SpinLock&) = delete;  // protects nothing

    void lock() {
        // acquire: everything in the critical section stays after this.
        while (held_.test_and_set(std::memory_order_acquire)) {
        }
    }

    void unlock() {
        // release: everything in the critical section stays before this.
        held_.clear(std::memory_order_release);
    }

private:
    std::atomic_flag held_ = ATOMIC_FLAG_INIT;
};

class SpinGuard {
public:
    explicit SpinGuard(SpinLock& lock) : lock_(lock) { lock_.lock(); }
    ~SpinGuard() { lock_.unlock(); }
    SpinGuard(const SpinGuard&) = delete;
    SpinGuard& operator=(const SpinGuard&) = delete;

private:
    SpinLock& lock_;
};

// This is BLOCKING, not lock-free. There is still a holder: if the
// thread inside the critical section is descheduled, page-faults, or
// suffers priority inversion, every spinner waits for it. Removing
// std::mutex removed an API, not the ownership.

#include <mutex>

class ConcurrentMap {
public:
    bool contains(int key) const;
    void insert(int key, int value);
    // One operation, one linearization point: the successful CAS (or
    // the internal lock acquisition) that installs the entry. Either
    // the key was absent at that instant and this call installed it, or
    // it was present and this call reports false. No other thread can
    // observe a state between the check and the act, because there is
    // no longer a gap to observe.
    bool insert_if_absent(int key, int value);
};

bool create_once(ConcurrentMap& map, int key, int value) {
    return map.insert_if_absent(key, value);
}

// Why the original was broken, and why memory orders cannot fix it:
//
// Linearizability composes at the OBJECT-OPERATION level. Both
// contains() and insert() may be individually linearizable while the
// client-side pair is not atomic: another thread linearizes its own
// insert between the two calls, and both callers proceed.
//
// The gap is a missing OPERATION BOUNDARY, not a missing ordering
// edge - seq_cst on every internal atomic would leave the interleaving
// exactly as legal. The alternative fix is to hold a lock across the
// pair, which supplies the same boundary from the outside.

std::mutex map_mutex;

bool create_once_locked(ConcurrentMap& map, int key, int value) {
    std::lock_guard lock{map_mutex};
    if (map.contains(key)) {
        return false;
    }
    map.insert(key, value);
    return true;
}

#include <algorithm>
#include <atomic>
#include <cstdint>
#include <thread>

std::atomic<std::uint64_t> counter{0};

void backoff(unsigned failures) {
    unsigned shift = std::min(failures, 8u);   // cap the doubling
    unsigned spins = 1u << shift;
    for (unsigned i = 0; i < spins; ++i) {
        // Keeps the empty spin from being optimised away. This is a
        // compiler barrier, NOT a processor pause instruction -
        // production wraps a target-specific pause behind a portability
        // shim.
        std::atomic_signal_fence(std::memory_order_seq_cst);
    }
    if (failures > 8) {
        std::this_thread::yield();  // escalate to the scheduler
    }
}

void increment() {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    // No reload in the loop body: a failed compare_exchange writes the
    // observed value back into `expected`, and the next attempt
    // computes its desired value from that observation.
    //
    // weak: this loop retries anyway, so a spurious failure costs one
    // iteration and avoids the nested retry strong CAS may need on an
    // LL/SC machine.
    for (unsigned failures = 0;
         !counter.compare_exchange_weak(expected, expected + 1,
                                        std::memory_order_relaxed);
         ++failures) {
        backoff(failures);
    }
}

// Backoff trades individual latency for less coherence traffic and can
// improve observed fairness. It does NOT promote this loop to
// wait-free, and it does not prevent one caller from starving: CAS
// fairness is not guaranteed. Constants tuned on one processor, core
// count, or scheduler are not universal.

#include <atomic>
#include <cstdint>

struct Quote {
    std::int64_t bid_ticks;
    std::int64_t ask_ticks;
};

class QuoteSeqLock {
public:
    // SINGLE WRITER ONLY. Multiple writers need a separate
    // serialization mechanism; nothing here provides one.
    void store(const Quote& quote) {
        sequence_.fetch_add(1, std::memory_order_relaxed);   // -> odd
        std::atomic_thread_fence(std::memory_order_release);
        bid_.store(quote.bid_ticks, std::memory_order_relaxed);
        ask_.store(quote.ask_ticks, std::memory_order_relaxed);
        sequence_.fetch_add(1, std::memory_order_release);   // -> even
    }

    Quote load() const {
        for (;;) {
            std::uint64_t before = sequence_.load(std::memory_order_acquire);
            if ((before & 1u) != 0) {
                continue;  // a write is in progress
            }

            Quote quote{bid_.load(std::memory_order_relaxed),
                        ask_.load(std::memory_order_relaxed)};

            std::atomic_thread_fence(std::memory_order_acquire);
            std::uint64_t after = sequence_.load(std::memory_order_relaxed);
            if (before == after) {
                return quote;  // equal EVEN counters bracket the reads
            }
        }
    }

private:
    // Payload fields are ATOMIC. Plain fields would race with the
    // writer, and discarding a torn snapshot afterwards does not repair
    // undefined behaviour.
    std::atomic<std::uint64_t> sequence_{0};
    std::atomic<std::int64_t> bid_{0};
    std::atomic<std::int64_t> ask_{0};
};

// The proof runs in two directions:
//  (1) If the reader observes a COMPLETED even generation, the writer's
//      final release increment published the corresponding payload, so
//      the relaxed loads observe it or something later.
//  (2) If the reader observes any field from an IN-PROGRESS generation,
//      the writer's odd increment is sequenced before its release
//      fence, so the reader's acquire fence forces its final sequence
//      load to see the odd value or later - and the equality check
//      fails.
//
// Assumptions: the counter must not complete a full wrap between the
// reader's two loads (a 64-bit counter makes that unreachable, but it
// is part of the proof, not a gift); and the payload must stay small
// and trivially copyable, since a large one widens the overlap window
// and turns write bursts into retry storms.

#include <cstdint>

struct Node {
    int value;
    Node* next;
};

struct TaggedPointer {
    static constexpr std::uint64_t address_mask =
        (std::uint64_t{1} << 48) - 1;

    static std::uint64_t pack(Node* pointer, std::uint16_t tag) {
        auto address = reinterpret_cast<std::uintptr_t>(pointer);
        return (std::uint64_t{tag} << 48) | (address & address_mask);
    }

    static Node* pointer(std::uint64_t packed) {
        auto address = static_cast<std::uintptr_t>(packed & address_mask);
        return reinterpret_cast<Node*>(address);
    }

    static std::uint16_t tag(std::uint64_t packed) {
        return static_cast<std::uint16_t>(packed >> 48);
    }
};

// PORTABILITY ASSUMPTION: usable pointers fit in the low 48 bits and
// round-trip after masking. That is a deployment-specific x86-64
// lower-address convention, not a property of C++. Five-level paging,
// hardware pointer tags, capability pointers, and different virtual
// address layouts all invalidate it.
//
// WHAT THIS DOES NOT FIX:
//  (1) Wraparound. A 16-bit generation repeats after 65,536 mutations
//      and can recreate an old packed value. The proof must BOUND the
//      mutations that can occur during the lifetime of any outstanding
//      observation - "unlikely" is not a proof.
//  (2) Lifetime. Tagging fixes IDENTITY COMPARISON only. A popping
//      thread still dereferences observed->next before its CAS, so it
//      still needs a reclamation protocol to keep that node alive.
//      Tagged pointers and safe reclamation solve different halves of
//      the stack problem.

#include <atomic>
#include <optional>

struct Node {
    int value;
    Node* next;
};

extern std::atomic<Node*> head;

class HazardSlot {
public:
    void publish(Node* node) {
        protected_.store(node, std::memory_order_seq_cst);
    }
    void clear() {
        protected_.store(nullptr, std::memory_order_seq_cst);
    }
    Node* get() const {
        return protected_.load(std::memory_order_seq_cst);
    }

private:
    std::atomic<Node*> protected_{nullptr};
};

std::optional<int> read_head(HazardSlot& hazard) {
    for (;;) {
        Node* node = head.load(std::memory_order_acquire);

        // PUBLISH FIRST. Validating first would leave a window in which
        // the node is unlinked and freed before this hazard becomes
        // visible to a scanning reclaimer - exactly the
        // reuse-before-read race the protocol exists to close.
        hazard.publish(node);

        // VALIDATE. If head still names the node, the publication was
        // already established at a point where the node was still
        // linked, so any later scan must observe it.
        if (node != head.load(std::memory_order_acquire)) {
            continue;  // republish the new candidate
        }

        if (node == nullptr) {
            hazard.clear();          // clear on the empty path too
            return std::nullopt;
        }

        int value = node->value;     // protected dereference
        hazard.clear();
        return value;
    }
}

// The reclaimer side: unlinked nodes go onto a per-thread RETIRED list;
// periodically the owner scans EVERY hazard slot and frees only those
// retired nodes that no slot names. Nodes still named are kept for the
// next scan. That is why clearing this thread's own slot after it is
// finished is safe: another thread's slot may still protect the node,
// and the scan honours it.

#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <type_traits>

template<class T, std::size_t N>
requires (std::is_nothrow_move_constructible_v<T> &&
          std::is_nothrow_move_assignable_v<T> &&
          std::is_nothrow_destructible_v<T>)
class SpscRing {
    // position & (N - 1) == position % N only for a power of two.
    static_assert(N > 0 && (N & (N - 1)) == 0);
    static_assert(std::atomic<std::uint64_t>::is_always_lock_free);

public:
    bool push(T&& value) noexcept {
        // tail_ is PRODUCER-OWNED: nobody else writes it, so relaxed.
        std::uint64_t tail = tail_.load(std::memory_order_relaxed);

        if (tail - cached_head_ == N) {
            // Only now pay for the peer's index. Acquire: head_ carries
            // the consumer's release publication that a slot was
            // drained and destroyed, and we are about to reuse it.
            cached_head_ = head_.load(std::memory_order_acquire);
            if (tail - cached_head_ == N) {
                return false;  // genuinely full
            }
        }

        slots_[tail & (N - 1)].emplace(std::move(value));
        // Release: publishes the constructed element to the consumer's
        // acquire load of tail_.
        tail_.store(tail + 1, std::memory_order_release);
        return true;
    }

    bool pop(T& value) noexcept {
        // head_ is CONSUMER-OWNED: relaxed for the same reason.
        std::uint64_t head = head_.load(std::memory_order_relaxed);

        if (cached_tail_ == head) {
            cached_tail_ = tail_.load(std::memory_order_acquire);
            if (cached_tail_ == head) {
                return false;  // genuinely empty
            }
        }

        auto& slot = slots_[head & (N - 1)];
        value = std::move(*slot);
        slot.reset();  // destroy BEFORE publishing the slot as free
        head_.store(head + 1, std::memory_order_release);
        return true;
    }

private:
    // Separate the producer-written state, the consumer-written state,
    // and the storage so unrelated writes do not share a line.
    alignas(64) std::atomic<std::uint64_t> head_{0};
    std::uint64_t cached_tail_{0};

    alignas(64) std::atomic<std::uint64_t> tail_{0};
    std::uint64_t cached_head_{0};

    alignas(64) std::array<std::optional<T>, N> slots_{};
};

#include <expected>
#include <span>
#include <utility>
#include <variant>

struct Trade { int price; int quantity; };
struct Quote { int price; int quantity; };
using Message = std::variant<Trade, Quote>;

enum class DecodeError {
    short_message, unknown_kind, missing_separator, invalid_number
};

std::expected<Message, DecodeError> decode(std::span<const char> packet);

void record_trade();
void record_quote();
void record_decode_error(DecodeError);
void record_queue_full();

template<class... Functions>
struct Overloaded : Functions... {
    using Functions::operator()...;
};

template<class Ring>
class Ingress {
public:
    explicit Ingress(Ring& output) : output_(output) {}

    void on_packet(std::span<const char> packet) {
        // OWNER: the caller owns the bytes and outlives this call. The
        // span borrows them; no view derived from it escapes.
        auto decoded = decode(packet);
        if (!decoded) {
            // Typed failure, not an exception and not a sentinel value.
            record_decode_error(decoded.error());
            return;
        }

        // OWNER: `decoded` owns either the variant or the error; moving
        // out of it transfers the fields into a local value.
        Message message = std::move(*decoded);

        // Closed set - std::visit is exhaustive at compile time, with
        // no virtual dispatch and no default case to rot.
        std::visit(Overloaded{
            [](const Trade&) { record_trade(); },
            [](const Quote&) { record_quote(); }
        }, message);

        // OWNER: a successful push moves ownership into one preallocated
        // ring slot. OVERLOAD POLICY: return failure and record it. The
        // producer neither blocks nor grows storage; a full queue is a
        // visible, measurable event that the caller can escalate.
        if (!output_.push(std::move(message))) {
            record_queue_full();
        }
    }

private:
    Ring& output_;
};
